insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f6861863-9b67-5f84-a968-d338d706bff0', '04b61e71-47e0-5a22-a027-969557678533', '12f9dd98-012f-5b0e-a17e-9e8d93e875d3', 'c427c2d4-2d6d-5ead-a625-79a9ad547cd6', 'Offshoring means…', '["Moving to the coast","Using local suppliers","Relocating business activities to another country","Opening an online shop"]'::jsonb, 'Often done to reduce costs.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
