insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('033e98af-9ff6-5500-a47d-a77d20dc031f', '04b61e71-47e0-5a22-a027-969557678533', '12f9dd98-012f-5b0e-a17e-9e8d93e875d3', 'c427c2d4-2d6d-5ead-a625-79a9ad547cd6', 'Lean production aims to…', '["Minimise waste of all resources","Slow down production","Maximise inventory","Increase labour costs"]'::jsonb, 'It includes JIT, kaizen and cell production.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
